package cli

import (
	"fmt"
	"strings"

	"github.com/seletz/odoo-work-cli/internal/mcp"
)

// MCPToolsReference renders the reference page of the MCP tools
// (docs/reference/60-mcp-tools.md) from the tool table, so the page cannot
// drift from the server. `go run ./tools/docsgen mcp` writes it; a test
// fails when the committed page is stale.
//
// :returns: the Markdown page
func MCPToolsReference() string {
	var b strings.Builder
	tools := mcpTools()
	b.WriteString(`---
title: MCP tools
icon: lucide/plug
---
<!-- Generated by ` + "`mise run docs:mcp`" + ` from internal/cli/mcp.go. Do not edit. -->
# MCP tools

The tools of ` + "`odoo-work-cli mcp`" + ` ([how to connect a client](../how-to/85-mcp.md)).
Each tool runs the CLI command in the second column with ` + "`--json`" + ` and
returns its JSON unchanged: the fields are those of
[JSON output](20-json-output.md), a failure is a result with ` + "`isError: true`" + `
and the [error envelope](30-errors.md). An argument is named like the flag,
with ` + "`_`" + ` for ` + "`-`" + `.

The annotations tell the client what a tool does: ` + "`readOnlyHint`" + ` (changes
nothing), ` + "`destructiveHint`" + ` (may overwrite or remove data) and
` + "`idempotentHint`" + ` (calling it again with the same arguments changes nothing
more). ` + "`odoo-work-cli mcp --read-only`" + ` serves only the read-only tools.

| Tool | Command | readOnlyHint | destructiveHint | idempotentHint |
| --- | --- | --- | --- | --- |
`)
	for _, t := range tools {
		readOnly, destructive, idempotent := t.Hints()
		fmt.Fprintf(&b, "| [`%s`](#%s) | `%s` | %s | %s | %s |\n", t.Name, t.Name,
			strings.Join(t.Command, " "), yesNo(readOnly), yesNo(destructive), yesNo(idempotent))
	}
	b.WriteString(`
Results over 32 KiB come in pages. The list tools take a ` + "`cursor`" + `
argument: the second content item of a paged result says which page it is
and gives ` + "`next.cursor`" + `; pass it unchanged, with the same other arguments,
for the next page.
`)
	for _, t := range tools {
		fmt.Fprintf(&b, "\n## `%s`\n\n%s\n\n", t.Name, t.Title)
		fmt.Fprintf(&b, "%s\n\n", t.Description)
		if len(t.Params) == 0 {
			b.WriteString("No arguments.\n")
			continue
		}
		b.WriteString("| Argument | Type | Required | Description |\n| --- | --- | --- | --- |\n")
		for _, p := range t.Params {
			fmt.Fprintf(&b, "| `%s` | %s | %s | %s |\n", p.Name, paramType(p), yesNo(p.Required), strings.ReplaceAll(p.Description, "|", `\|`))
		}
	}
	return b.String()
}

func yesNo(v bool) string {
	if v {
		return "yes"
	}
	return "no"
}

func paramType(p mcp.Param) string {
	if p.Type == "string" && p.Number {
		return "number or string"
	}
	return p.Type
}
